type PortfolioMedia={isCover:boolean;url:string|null;media:{mediaType:'IMAGE'|'VIDEO';thumbnailPath:string|null}};
type PortfolioPost={id:string;caption:string|null;eventType:string|null;tags:string[];format:string;business:{name:string;slug:string};category:{name:string};city:{name:string};media:PortfolioMedia[]};
async function loadPortfolio(slug:string):Promise<PortfolioPost[]>{try{const response=await fetch(`http://localhost:4000/api/v1/public/vendors/${encodeURIComponent(slug)}/portfolio`,{cache:'no-store'});return response.ok?await response.json() as PortfolioPost[]:[]}catch{return[]}}
export default async function PublicPortfolio({params}:{params:Promise<{slug:string}>}){const{slug}=await params,posts=await loadPortfolio(slug),vendor=posts[0]?.business.name??slug.split('-').map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ');return <main className="portfolio-page"><header className="portfolio-header"><a className="brand" href="/">WedConnect</a><span>Portfolio</span></header><section className="portfolio-intro"><p className="eyebrow">Wedding professional</p><h1>{vendor}</h1><p>{posts.length?`${posts.length} approved portfolio ${posts.length===1?'story':'stories'}`:'Approved work will appear here after media processing and moderation.'}</p></section>{posts.length?<section className="portfolio-grid">{posts.map(post=>{const cover=post.media.find(x=>x.isCover)??post.media[0];return <article className="portfolio-card" key={post.id}>{cover?.url?(cover.media.mediaType==='VIDEO'?<video controls poster={cover.url}><source src={cover.url}/></video>:<img src={cover.url} alt={post.caption??`${post.category.name} work in ${post.city.name}`}/>):<div className="media-placeholder">Processing media</div>}<div><span>{post.eventType??post.category.name} · {post.city.name}</span><h2>{post.caption??post.category.name}</h2><p>{post.tags.map(tag=>`#${tag}`).join(' ')}</p><button type="button">Request similar service</button></div></article>})}</section>:<section className="empty-portfolio"><span>◇</span><h2>No published portfolio yet</h2><p>Uploads stay private until processing and moderation are complete.</p></section>}</main>}
